html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro lines(value, blank=3) -%}
{%- if value %}<p class="answer">{{ v(value) | replace("\n", "<br>") }}</p>{% else %}{% for i in range(blank) %}<p class="dots"></p>{% endfor %}{% endif -%}
{%- endmacro -%}
{%- macro person(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}<style>
	.lpl { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; }
	.lpl table { width: 100%; border-collapse: collapse; margin: 0 0 8px; }
	.lpl tr { page-break-inside: avoid; }
	.lpl td, .lpl th { border: 1px solid #555; padding: 4px 6px; vertical-align: top; text-align: left; }
	.lpl th, .lpl td.lbl { background: #f2f2f2; font-weight: bold; }
	.lpl td.val { height: 18px; }
	.lpl .head td { vertical-align: middle; font-weight: bold; }
	.lpl .head .title { text-align: center; }
	.lpl .no { width: 26px; background: #f2f2f2; font-weight: bold; }
	.lpl .num { width: 13%; text-align: center; }
	.lpl h4 { font-size: 11.5px; font-weight: bold; text-decoration: underline; margin: 12px 0 4px; }
	.lpl p { margin: 0 0 4px; }
	.lpl .q { font-weight: bold; margin: 10px 0 3px; }
	.lpl .answer { border-bottom: 1px dotted #777; padding: 0 0 3px; }
	.lpl .dots { border-bottom: 1px dotted #777; height: 16px; margin: 0; }
	.lpl table.plain td { border: none; padding: 10px 0 0; }
	.lpl .ref { text-align: right; font-size: 9.5px; }
	.lpl .box { display: inline-block; width: 12px; height: 12px; border: 1px solid #000; margin-right: 6px; text-align: center; line-height: 11px; }
</style>
<div class="lpl">
	<table class="head">
		<tr>
			<td style="width: 22%; text-align: center">{% if logo %}<img src="{{ logo }}" style="max-height: 50px">{% endif %}</td>
			<td class="title">Recruitment Process<br>Staff Onboarding Form</td>
			<td style="width: 22%; text-align: center">LPL/HR/04, Rev1 15/06/2025</td>
		</tr>
	</table>
	<p><strong>{{ v(doc.review_day) }}-day review</strong>{% if doc.due_date %}, due {{ day(doc.due_date) }}{% endif %}</p>
	<p class="q">Purpose;</p>
	<p>To provide the new staff with guidance and set expectations in order to empower them to hit the ground running from day one.</p>

	<h4>Section A:</h4>
	<table>
		<tr>
			<td class="lbl" style="width: 20%">Name of Employee:</td><td style="width: 32%">{{ v(doc.employee_name) }}</td>
			<td class="lbl" style="width: 18%">Date of Joining:</td><td>{{ day(doc.date_of_joining) }}</td>
		</tr>
		<tr>
			<td class="lbl">Department:</td><td>{{ v(doc.department) }}</td>
			<td class="lbl">Job Title:</td><td>{{ v(doc.designation) }}</td>
		</tr>
	</table>

	<h4>Section B:</h4>
	<p class="q">List down the roles and responsibilities of your position in the company</p>
	{%- set roles = (doc.roles_responsibilities or "").split("\n") | map("trim") | select | list -%}
	<table>
		{%- for i in range([roles | length, 5] | max) %}
		<tr><td class="no">{{ ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"][i] if i < 10 else i + 1 }}.</td><td class="val">{{ v(roles[i] if i < roles | length else "") }}</td></tr>
		{%- endfor %}
	</table>
	<p class="q">How do you feel about your new role and responsibilities?</p>
	{{ lines(doc.feel_about_role, 5) }}
	<p class="q">Describe how the onboarding process helped you understand the company culture and values?</p>
	{{ lines(doc.culture_values, 4) }}
	<p class="q">How satisfied are you with the communication and support provided during onboarding?</p>
	{{ lines(doc.communication_support, 3) }}
	<p class="q">Can you share any achievements from the handover to your department?</p>
	{{ lines(doc.handover_achievements, 4) }}
	<p class="q">Can you share any challenges faced during onboarding?</p>
	{{ lines(doc.onboarding_challenges, 4) }}
	<p class="q">Do you think the onboarding process should be improved?</p>
	<p><span class="box">{{ "&#10003;" if doc.improve_onboarding == "Yes" else "" }}</span>Yes &nbsp; &nbsp;
		<span class="box">{{ "&#10003;" if doc.improve_onboarding == "No" else "" }}</span>No</p>
	<p class="q">If yes, explain how best we can improve.</p>
	{{ lines(doc.improvement_suggestions, 4) }}

	<p class="q">General comments by the New Employee:</p>
	{{ lines(doc.employee_comments, 2) }}
	<table class="plain"><tr><td style="width: 50%">Sign.............................................</td><td>Date {{ day(doc.employee_signed_on) or "............................................." }}</td></tr></table>
	<p class="q">General comments by the Supervisor of the New Employee:</p>
	{{ lines(doc.supervisor_comments, 2) }}
	<table class="plain"><tr><td style="width: 50%">Sign {{ person(doc.supervisor_by) or "............................................." }}</td><td>Date {{ day(doc.supervisor_on) or "............................................." }}</td></tr></table>
	<p class="q">Human Resources Manager's remarks:</p>
	{{ lines(doc.hrm_remarks, 2) }}
	<table class="plain"><tr><td style="width: 50%">Sign {{ person(doc.hrm_by) or "............................................." }}</td><td>Date {{ day(doc.hrm_on) or "............................................." }}</td></tr></table>
	<p class="ref">LPL/HR/04, Rev1 15/06/2025</p>
</div>
